-- Adds a full ride & show catalog (from a spreadsheet export) on top of
-- the small seed set in 20260826000330_wishlist.sql, plus a new 'show'
-- wish list category for Shows & Entertainment. 17 rides already existed
-- in the catalog (r-tron, r-haunted, etc.) and keep their ids — this just
-- refreshes their description and backfills lightning_lane_tier.
alter table catalog_items add column if not exists lightning_lane_tier text;

on conflict (id) do update set
  name = excluded.name, park = excluded.park, category = excluded.category,
  description = excluded.description, lightning_lane_tier = excluded.lightning_lane_tier;
