insert into catalog_items (id, name, park, category, description, price_label, price_mid, lightning_lane_tier) values
  ('r-7dmt', 'Seven Dwarfs Mine Train', 'MK', 'ride', 'A wildly popular junior coaster through Snow White''s diamond mine, featuring swaying mine cars and glittering gem scenes. One of the most-sought tickets in the park.', '', 0, 'single_pass'),
  ('r-tron', 'TRON Lightcycle / Run', 'MK', 'ride', 'A high-speed outdoor launch coaster modeled after a lightcycle from the TRON films. Guests board motorbike-style vehicles and race through a stunning neon grid at up to 60 mph.', '', 0, 'single_pass'),
  ('r-btmr', 'Big Thunder Mountain Railroad', 'MK', 'ride', 'A rollicking runaway mine train coaster through a haunted gold rush canyon. A family favorite with a newly lowered 38" height requirement.', '', 0, 'multi_pass_tier1'),
  ('r-jungle-cruise', 'Jungle Cruise', 'MK', 'ride', 'A classic boat ride through animatronic jungle scenes of Africa, Asia, and South America, narrated by punny skippers. Iconic Disney humor throughout.', '', 0, 'multi_pass_tier1'),
  ('r-peter-pan-s-flight', 'Peter Pan''s Flight', 'MK', 'ride', 'One of the park''s most beloved dark rides — a gentle flying ship glides over nighttime London and into Neverland. Simple, magical, and perpetually popular with all ages.', '', 0, 'multi_pass_tier1'),
  ('r-smtn', 'Space Mountain', 'MK', 'ride', 'An indoor roller coaster through simulated deep space — twists and drops in near-total darkness with a retro-futuristic soundtrack. A Magic Kingdom staple since 1975.', '', 0, 'multi_pass_tier1'),
  ('r-tiana', 'Tiana''s Bayou Adventure', 'MK', 'ride', 'A log flume adventure through the Louisiana bayou with Princess Tiana and friends. The reimagined successor to Splash Mountain with original music and vibrant storytelling.', '', 0, 'multi_pass_tier1'),
  ('r-buzz-lightyear-s-space-ranger', 'Buzz Lightyear''s Space Ranger Spin', 'MK', 'ride', 'An interactive dark ride where guests join Buzz battling Emperor Zurg, firing laser cannons at targets to rack up points. Reopened in 2026 with new vehicles and characters.', '', 0, 'multi_pass_tier2'),
  ('r-dumbo-the-flying-elephant', 'Dumbo the Flying Elephant', 'MK', 'ride', 'A classic gentle spinner where guests ride in elephant-shaped vehicles and control their own height. A must-do for the youngest park guests.', '', 0, 'multi_pass_tier2'),
  ('r-haunted', 'Haunted Mansion', 'MK', 'ride', 'A slow-moving Doom Buggy tour through a ghost-filled manor with 999 happy haunts. One of Disney''s most elaborate dark rides with brilliant special effects.', '', 0, 'multi_pass_tier2'),
  ('r-it-s-a-small-world', '"it''s a small world"', 'MK', 'ride', 'A gentle boat ride through colorful scenes of children from around the world, all singing the iconic theme song. Air-conditioned and classic — perfect for all ages.', '', 0, 'multi_pass_tier2'),
  ('r-mad-tea-party', 'Mad Tea Party', 'MK', 'ride', 'The classic spinning teacup ride where guests control how fast their cup rotates. Great for kids who love to spin — or adults who dare them to.', '', 0, 'multi_pass_tier2'),
  ('r-pirates-of-the-caribbean', 'Pirates of the Caribbean', 'MK', 'ride', 'A boat ride through scenes of pirate raids, treasure, and swashbuckling adventure. Jack Sparrow makes appearances in this timeless classic.', '', 0, 'multi_pass_tier2'),
  ('r-the-barnstormer', 'The Barnstormer', 'MK', 'ride', 'A small, zippy roller coaster themed around Goofy''s crop-duster stunt flying. Ideal for young first-time coaster riders looking for a gentle thrill.', '', 0, 'multi_pass_tier2'),
  ('r-the-many-adventures-of-winnie', 'The Many Adventures of Winnie the Pooh', 'MK', 'ride', 'A gentle dark ride through the Hundred Acre Wood following Pooh''s dream of honey and his friends. Colorful and calm — perfect for toddlers.', '', 0, 'multi_pass_tier2'),
  ('r-tomorrowland-speedway', 'Tomorrowland Speedway', 'MK', 'ride', 'Gas-powered cars on a guided track let kids feel like they''re really driving. Slow, loud, and beloved by children who can''t wait to get behind the wheel.', '', 0, 'multi_pass_tier2'),
  ('r-under-the-sea-journey-of-the', 'Under the Sea ~ Journey of the Little Mermaid', 'MK', 'ride', 'A slow clamshell ride through scenes from The Little Mermaid with bright animatronics and beloved songs. A gentle, family-friendly journey under the sea.', '', 0, 'multi_pass_tier2'),
  ('r-walt-disney-world-railroad', 'Walt Disney World Railroad', 'MK', 'ride', 'A steam-powered train circumnavigating the park with stops at Main Street, Frontierland, and Fantasyland. A relaxing way to travel between lands.', '', 0, 'standby_only'),
  ('r-prince-charming-regal', 'Prince Charming Regal Carrousel', 'MK', 'ride', 'A beautifully ornate antique carousel with horses rising and falling to classic Disney tunes. The oldest attraction at Walt Disney World, dating to 1917.', '', 0, 'standby_only'),
  ('r-tom-sawyer-island', 'Tom Sawyer Island', 'MK', 'ride', 'A raft-access island with caves, bridges, and a fort to explore on foot. A rare unstructured, self-guided experience great for kids who need a break from lines.', '', 0, 'standby_only'),
  ('r-astro-orbiter', 'Astro Orbiter', 'MK', 'ride', 'A spinning rocket ride high above Tomorrowland where guests control their altitude. Offers great views of the park with a slight thrill from the height.', '', 0, 'standby_only'),
  ('r-sorcerers-of-the-magic-kingdom', 'Sorcerers of the Magic Kingdom', 'MK', 'ride', 'An interactive card game where guests cast spells to battle Disney villains hidden in storefronts throughout the park. A slow-paced scavenger hunt between rides.', '', 0, 'standby_only'),
  ('r-gotg', 'Guardians of the Galaxy: Cosmic Rewind', 'EPCOT', 'ride', 'A reverse-launch indoor coaster with a rotating ride vehicle set to an awesome mixtape. EPCOT''s hottest ticket — guests chase Guardians characters through space.', '', 0, 'single_pass'),
  ('r-frozen', 'Frozen Ever After', 'EPCOT', 'ride', 'A boat ride through the Kingdom of Arendelle featuring Anna, Elsa, Olaf, and Sven with beloved songs from the film. One of EPCOT''s most popular family attractions.', '', 0, 'multi_pass_tier1'),
  ('r-remy', 'Remy''s Ratatouille Adventure', 'EPCOT', 'ride', 'A trackless ride that shrinks guests to the size of a rat and sends them scurrying through Gusteau''s restaurant. Charming storytelling with appeal across all ages.', '', 0, 'multi_pass_tier1'),
  ('r-testtrack', 'Test Track', 'EPCOT', 'ride', 'Guests design a simulated vehicle and put it through performance tests — culminating in a high-speed exterior circuit reaching 65 mph. Recently reimagined.', '', 0, 'multi_pass_tier1'),
  ('r-living-with-the-land', 'Living with the Land', 'EPCOT', 'ride', 'A peaceful boat ride through EPCOT''s working greenhouses and aquaculture facilities, showcasing real innovations in sustainable food growing. Surprisingly fascinating.', '', 0, 'multi_pass_tier2'),
  ('r-mission-space', 'Mission: SPACE', 'EPCOT', 'ride', 'A centrifuge-based space flight simulator with two modes: the intense Orange Mission to Mars, or the gentler Green Mission orbiting Earth.', '', 0, 'multi_pass_tier2'),
  ('r-soarin-across-america', 'Soarin'' Across America', 'EPCOT', 'ride', 'A hang-gliding film simulator featuring sweeping cinematography of American landscapes. Updated in 2026 with an all-new film for the U.S. 250th anniversary.', '', 0, 'multi_pass_tier2'),
  ('r-se', 'Spaceship Earth', 'EPCOT', 'ride', 'A slow omnimover ride up through the iconic geodesic sphere, chronicling the history of human communication. Thoughtful, relaxing, and quintessentially EPCOT.', '', 0, 'multi_pass_tier2'),
  ('r-the-seas-with-nemo-and-friends', 'The Seas with Nemo & Friends', 'EPCOT', 'ride', 'A clamshell ride through the ocean to find Nemo among EPCOT''s massive saltwater aquariums. Gentle and colorful — leads into the Living Seas pavilion for real marine life.', '', 0, 'multi_pass_tier2'),
  ('r-gran-fiesta-tour-starring-the', 'Gran Fiesta Tour Starring the Three Caballeros', 'EPCOT', 'ride', 'A slow boat ride through Mexico''s World Showcase pavilion following the Three Caballeros on a colorful musical journey. A relaxing indoor attraction.', '', 0, 'standby_only'),
  ('r-rotr', 'Star Wars: Rise of the Resistance', 'HS', 'ride', 'The most ambitious attraction Disney has ever built — part trackless dark ride, part drop, part walkthrough. Guests are captured by the First Order in a multi-room epic experience.', '', 0, 'single_pass'),
  ('r-mickey-and-minnie-s-runaway', 'Mickey & Minnie''s Runaway Railway', 'HS', 'ride', 'A zany trackless dark ride inside the Chinese Theatre where guests enter a cartoon world with Mickey, Minnie, and Goofy. Dazzling cartoon-physics gags for all ages.', '', 0, 'multi_pass_tier1'),
  ('r-falcon', 'Millennium Falcon: Smugglers Run', 'HS', 'ride', 'Guests pilot the actual Millennium Falcon as pilots, gunners, or engineers. Ride outcome varies by crew performance — a wildly interactive cockpit experience.', '', 0, 'multi_pass_tier1'),
  ('r-rock-n-roller-coaster', 'Rock ''n'' Roller Coaster Starring the Muppets', 'HS', 'ride', 'A high-speed indoor launch coaster reimagined with a Muppets theme. Launches from 0 to 57 mph in seconds with inversions in the dark. Reopened May 2026.', '', 0, 'multi_pass_tier1'),
  ('r-slinky', 'Slinky Dog Dash', 'HS', 'ride', 'A family coaster where guests ride Slinky Dog through a twisty track Andy built in his backyard. Smooth, fun, and consistently one of the park''s highest-demand rides.', '', 0, 'multi_pass_tier1'),
  ('r-alien-swirling-saucers', 'Alien Swirling Saucers', 'HS', 'ride', 'A spinning ride on flying saucers piloted by Little Green Aliens. Gentle and colorful — ideal for young kids visiting Toy Story Land.', '', 0, 'multi_pass_tier2'),
  ('r-star-tours-the-adventures', 'Star Tours – The Adventures Continue', 'HS', 'ride', 'A motion simulator with randomized Star Wars destinations and characters — each ride is a different combination of locations and story beats from across the saga.', '', 0, 'multi_pass_tier2'),
  ('r-the-twilight-zone-tower-of', 'The Twilight Zone Tower of Terror', 'HS', 'ride', 'A haunted hotel drop ride themed around The Twilight Zone. Guests experience unpredictable freefall sequences in an elevator through a ghost-filled Hollywood hotel.', '', 0, 'multi_pass_tier2'),
  ('r-toy-story-mania', 'Toy Story Mania!', 'HS', 'ride', 'An interactive 4D ride-through carnival game where guests shoot at targets on a midway through Andy''s room. Competitive and fun — scores are tracked per rider.', '', 0, 'multi_pass_tier2'),
  ('r-fop', 'Avatar Flight of Passage', 'AK', 'ride', 'A breathtaking flying simulator bonding guests with a banshee and soaring over Pandora. Routinely the longest standby line at Walt Disney World — Single Pass is strongly recommended.', '', 0, 'single_pass'),
  ('r-everest', 'Expedition Everest', 'AK', 'ride', 'A fast-paced roller coaster through the Himalayas that encounters the mythical Yeti — including a terrifying backward section in the dark. The park''s premier thrill ride.', '', 0, 'multi_pass'),
  ('r-safaris', 'Kilimanjaro Safaris', 'AK', 'ride', 'An open-air truck safari through a 110-acre savanna with real African animals — giraffes, elephants, lions, rhinos, and more. The cornerstone of Animal Kingdom.', '', 0, 'multi_pass'),
  ('r-na-vi-river-journey', 'Na''vi River Journey', 'AK', 'ride', 'A serene boat ride through the bioluminescent rainforest of Pandora, culminating in a stunning Na''vi Shaman animatronic. Most vivid after dark.', '', 0, 'multi_pass'),
  ('r-kali-river-rapids', 'Kali River Rapids', 'AK', 'ride', 'A circular raft ride through a deforested logging site — guests get splashed, sometimes soaked. A fun, cooling ride on hot days with an environmental message.', '', 0, 'multi_pass'),
  ('r-wildlife-express-train', 'Wildlife Express Train', 'AK', 'ride', 'A train ride from Harambe to Rafiki''s Planet Watch, home of Bluey''s Wild World. Required transport to reach Conservation Station.', '', 0, 'standby_only'),
  ('r-primeval-whirl', 'Primeval Whirl', 'AK', 'ride', 'A spinning wild mouse coaster through a time-travel storyline. In the former DinoLand area, which is being converted to Tropical Americas by 2027.', '', 0, 'standby_only'),
  ('w-mickey-s-philharmagic', 'Mickey''s PhilharMagic', 'MK', 'show', 'A 3D immersive theater show featuring Donald Duck on a magical musical adventure through classic Disney films. Aromas, breezes, and surprises make it a fan favorite.', '', 0, 'multi_pass_tier2'),
  ('w-monsters-inc-laugh-floor', 'Monsters Inc. Laugh Floor', 'MK', 'show', 'An interactive comedy show where animated monsters gather laughs from the audience — and audience members can text jokes that Mike Wazowski just might use on stage.', '', 0, 'multi_pass_tier2'),
  ('w-carousel-of-progress', 'Carousel of Progress', 'MK', 'show', 'A rotating theater show celebrating American technological progress through the decades. One of Walt Disney''s personal favorites — currently being updated.', '', 0, 'standby_only'),
  ('w-disney-and-pixar-short-film', 'Disney and Pixar Short Film Festival', 'EPCOT', 'show', 'A 4D theater experience featuring beloved animated short films from Disney and Pixar. A relaxed, entertaining break with charming sensory effects throughout.', '', 0, 'multi_pass_tier2'),
  ('w-journey-into-imagination-with', 'Journey into Imagination with Figment', 'EPCOT', 'show', 'A beloved dark ride/show hybrid starring Figment the purple dragon exploring the power of imagination. A quirky EPCOT classic with a devoted fanbase and catchy theme song.', '', 0, 'multi_pass_tier2'),
  ('w-turtle-talk-with-crush', 'Turtle Talk with Crush', 'EPCOT', 'show', 'An interactive show where Crush the sea turtle ''talks'' live with audience members using real-time animation technology. Kids love it — surprisingly impressive tech.', '', 0, 'multi_pass_tier2'),
  ('w-reflections-of-china', 'Reflections of China', 'EPCOT', 'show', 'A Circle-Vision 360° film presenting stunning footage of China''s landscapes and culture on a panoramic screen surrounding guests. A standing film — no seats.', '', 0, 'standby_only'),
  ('w-beauty-and-the-beast-live-on', 'Beauty and the Beast Live on Stage', 'HS', 'show', 'A 25-minute Broadway-style stage show featuring scenes from Beauty and the Beast with costumes, singing, and dancing. A wonderful mid-day break for families.', '', 0, 'multi_pass_tier2'),
  ('w-for-the-first-time-in-forever', 'For the First Time in Forever: A Frozen Sing-Along Celebration', 'HS', 'show', 'A comedic, audience-participation sing-along show celebrating the story of Frozen with live performers and video segments. Perfect for Frozen fans of all ages.', '', 0, 'multi_pass_tier2'),
  ('w-indiana-jones-epic-stunt', 'Indiana Jones Epic Stunt Spectacular', 'HS', 'show', 'A live outdoor stunt show recreating scenes from Raiders of the Lost Ark, with real explosions, fire, and action sequences. An entertaining classic.', '', 0, 'multi_pass_tier2'),
  ('w-disney-jr-mickey-mouse', 'Disney Jr. Mickey Mouse Clubhouse Live!', 'HS', 'show', 'A live-action dance party show featuring characters from Disney Jr. programming. Best suited to the youngest park guests.', '', 0, 'multi_pass_tier2'),
  ('w-the-little-mermaid-a-musical', 'The Little Mermaid – A Musical Adventure', 'HS', 'show', 'A live Broadway-quality stage production of The Little Mermaid with stunning costumes, puppetry, and vocals. A real theatrical treat tucked into the park.', '', 0, 'multi_pass_tier2'),
  ('w-muppet-vision-3d', 'Muppet*Vision 3D', 'HS', 'show', 'A classic Muppets 3D theater experience with physical special effects and audio-animatronic Statler and Waldorf in the balcony. A crowd-pleasing show for all generations.', '', 0, 'standby_only'),
  ('w-fantasmic', 'Fantasmic!', 'HS', 'show', 'A nighttime outdoor spectacular featuring Mickey Mouse battling Disney villains with water screens, fireworks, live performers, and floats on a lagoon stage. One of Disney''s best shows.', '', 0, 'standby_only'),
  ('w-finding-nemo-the-big-blue-and', 'Finding Nemo: The Big Blue…and Beyond!', 'AK', 'show', 'A live musical show featuring beloved characters from Finding Nemo — Nemo, Dory, Crush, and Bruce — performed with puppetry and live actors.', '', 0, 'multi_pass'),
  ('w-zootopia-better-zoogether', 'Zootopia: Better Zoogether!', 'AK', 'show', 'Guests help Judy Hopps and Nick Wilde solve a mystery in this new interactive, technology-driven show experience.', '', 0, 'multi_pass'),
  ('w-festival-of-the-lion-king', 'Festival of the Lion King', 'AK', 'show', 'A high-energy, Broadway-style theatrical show with singers, dancers, acrobats, and elaborate floats celebrating The Lion King. One of Disney World''s best live entertainment offerings.', '', 0, 'multi_pass'),
  ('w-feathered-friends-in-flight', 'Feathered Friends in Flight!', 'AK', 'show', 'An outdoor bird show featuring free-flying exotic birds — macaws, kites, and more — in impressive aerial demonstrations. Entertaining and educational.', '', 0, 'multi_pass'),
  ('w-up-a-great-bird-adventure', 'UP! A Great Bird Adventure', 'AK', 'show', 'An outdoor bird show featuring characters from Pixar''s UP alongside free-flying birds from around the world. A fun, family-friendly show held in the Caravan Stage.', '', 0, 'standby_only'),
  ('w-maharajah-jungle-trek', 'Maharajah Jungle Trek', 'AK', 'show', 'A self-guided walking trail through Asian-themed environments with tigers, giant fruit bats, Komodo dragons, and tropical birds. A relaxing pace-breaker with incredible animals.', '', 0, 'standby_only'),
  ('w-gorilla-falls-exploration', 'Gorilla Falls Exploration Trail', 'AK', 'show', 'A walking trail through an African forest setting with lowland gorillas, hippos, meerkats, okapis, and exotic birds. The gorilla habitat is a highlight for many guests.', '', 0, 'standby_only')
